    if (!array_key_exists($command, SCHEMAS)) {
        fail('unknown command');
    } else {
        $kinds = SCHEMAS[$command] === '' ? [] : explode(' ', SCHEMAS[$command]);
        $last = $kinds[count($kinds) - 1] ?? '';
